<span class="line">            <span class="token keyword">return</span> <span class="token keyword">this</span><span class="token punctuation">.</span>frameCache<span class="token punctuation">.</span><span class="token function">get</span><span class="token punctuation">(</span>videoUrl<span class="token punctuation">)</span></span>
